Method.Implementation:
//$$$TRACE("Inside  Method OnGetConnections")
Do ##super(.pArray,pItem)
If pItem.GetModifiedSetting("TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}

	set pResponse=##class(IHC.ITF.Response.MedOrderDbResponse).%New()
	set pResp=##class(IHC.ITF.Response.ProcessMedOrder).%New()

	Do ..ConnectionAndStatments() // Creates a connection and creates one statment for each different queries 

	//Do ..MainQueryStmt.setLong(1,3262650452)
	Do ..MainQueryStmt.setString(1,"P")
	set tResult = ..MainQueryStmt.executeQuery()

	set RecordCount = 0
	set ProcessedCount = 0
	set FilteredCount = 0

	// Process each record got from Staging
	while tResult.next() 
	{
		set RecordCount = RecordCount+1
		$$$TRACE("  ************** Processing Record Number : "_RecordCount)
		Do ..ClearProcessMedOrder(pResp) //Clearing all the values in the object for processing next record

		$$$TRACE("  Processing Event_ID : "_tResult.getString(2))
		set ..isPreProcessed = 1 // Resetting the Flag value for the next record
	    set ..editVersion = 0 // Resetting the  value for the next record
	    set ..SIGText=""  // Resetting the  value for the next record 

	//Check record with Processed Orders
	Do ..ProcessedOrdersStmt.setLong(1,tResult.getString(2))
	set tResultProcessedOrd = ..ProcessedOrdersStmt.executeQuery()

	// If entry exists in Processed Orders, Set Processed flag as "Y"
		if tResultProcessedOrd.next() 
		{
			set ..isPreProcessed = 0 //0 means true - This is a flag to identify if the record is pre processed. this will be used below in ORC segment
		    set ..editVersion = tResultProcessedOrd.getString(2) // Setting this value to use in method to update ProcessedOrder table if necessary 

		    //Check If the EditVersion in Staging is less than or equal to the EditVersion of ProcessedOrders, then row is already processed
		    if tResult.getString(3) <= tResultProcessedOrd.getString(2)
		    {
		    //Setting Processed Flag as "Y" in Staging
			set upStatus = ..UpdatePreviousProcessed("Y",tResultProcessedOrd.getString(1))
		    set FilteredCount = FilteredCount+1
		    CONTINUE
		    }

		}

		//  If entry does not exists in Processed Orders or if editversion matched the criteria, Set Processed flag as "P" to indicate the record is in Process
		set upStatus = ..UpdatePreviousProcessed("P",tResult.getString(2))

		//Do Filtering Logic
		set isfiltered = ..FilterMessages(tResult)

		if isfiltered = 1
		{
			$$$TRACE(" Record Filtered.. Proceding to next record")
		  	set filterupdateStatus = ..UpdatePreviousProcessed("Y",tResultProcessedOrd.getString(1))
		 	set FilteredCount = FilteredCount+1
		  	CONTINUE
		}

		set pResp.EventID = tResult.getString(2) // Set event id , for testing

		//Process MSH Segment
		Do ..ProcessMSHSegment(pResp)

		//Process PID Segment
		Do ..ProcessPIDSegment(pResp,tResult)

		//Process ORC Segment
		Do ..ProcessORCSegment(pResp,tResult)

		//Process ORM Segment
		Do ..ProcessRXOSegment(pResp,tResult)

		//Process NTE Segment
		Do ..ProcessNTESegment(pResp,tResult)

		//Process RXR Segment
		Do ..ProcessRXRSegment(pResp,tResult)


		//Update ProcessedOrders Table
		set upStatusFinal2 = ..UpdateProcessedOrders(tResult.getString(2),pResp)


        // Final update of Processed Flag as "Y
        set upStatusFinal = ..UpdatePreviousProcessed("Y",tResult.getString(2))


		set ..isPreProcessed = 1 // Resetting the Flag value for the next record
		set ..editVersion = 0 // Resetting the value for the next record

		set Hl7String = ..ConstructHl7(pResp)
		Set hl7Message = ##class(EnsLib.HL7.Message).ImportFromString(Hl7String)
		set sendRecordStatus=..SendRequestAsync(..TargetConfigNames,hl7Message,"CreatedHl7Message")
		set ProcessedCount = ProcessedCount+1 //Get the record count of Successfully processed records
		$$$TRACE(" Record with EventId "_pResp.EventID_" send to down")


    }
    do tResult.close() // Closing the Resultset
    set pResp.ProcessedRecordCount = ProcessedCount
    set pResp.FilteredRecordCount = FilteredCount
    $$$TRACE(" ProcessedCount : "_ProcessedCount)
    $$$TRACE(" FilteredCount : "_FilteredCount)

    //Add the last record object to list so that the call is made again . this is used if we are processing records in chunks 
    if ProcessedCount '=0
    {
    	//do pResponse.ResponseList.Insert(pResp)
    }

    Do ..connection.close()
    Do ..gateway.%Disconnect()

    $$$TRACE("  No Record ")
	quit pResponse

	// Set ORC01

	if (resultRecord.getString(6) = 1555) && (..isPreProcessed = 1)
	{
		set pResp.ORC01OrderControl = "NW"
	}
	elseif (resultRecord.getString(6) = 1555) && (..isPreProcessed = 0)
	{
		set pResp.ORC01OrderControl = "XO"
	}
	elseif resultRecord.getString(6) = 1524
	{
		set pResp.ORC01OrderControl = "DC"
	}

	//Set ORC2.1
	Do ..AListStmt.setLong(1,resultRecord.getString(2))
	set tResultAList = ..AListStmt.executeQuery()

	// If entry exists in A_LIST Orders, Append "A" to Event id and set in ORC2.1
	if tResultAList.next() 
	{
		//set pResp.ORC0201UniquePlacerNo = "A"_resultRecord.getString(2)
		//New requirment to add what ever present A_List table column value to the Event Id instead of "A"
		set pResp.ORC0201UniquePlacerNo = tResultAList.getString(2)_resultRecord.getString(2)
	}
	else
	{
		set pResp.ORC0201UniquePlacerNo = resultRecord.getString(2)
	}

	do tResultAList.close() //Closing the Result Set 

	set pResp.ORC0202PlacerAppId = ""

	//IF Sort_NCID =  521051182 AND ORC.01 is set to ‘NW’ THEN ‘H’ ELSE ‘O’

	if (resultRecord.getString(25) = 521051182) && (pResp.ORC01OrderControl = "NW")
	{
		set pResp.ORC05OrderStatus = "H"
	}
	else
	{
		set pResp.ORC05OrderStatus = "O"
	}




	Do ..setORC07QuantityTiming(pResp,resultRecord) 	

	//Date format we get from DB is 2015-10-14 06:00:00.0 if no time is given in DB	
	set SQLDate = $REPLACE(resultRecord.getString(4),"-","") //Remove the "-" {20151014 06:00:00.0}
	set SQLDate = $REPLACE(SQLDate," ","") // Remove the space {2015101406:00:00.0}
	set SQLDate = $REPLACE(SQLDate,":","") // Remove the ":" {201510140600:00.0}
	Set SQLDate = $EXTRACT(SQLDate,0,12) // {201510140600}
	Set JustDate = $EXTRACT(SQLDate,0,8) // {20151014}

	//We are going to check if time is 06:00.it means it is the default from DB and we going to change it to 00:00
	if SQLDate = JustDate_"0600"
	{
		set pResp.ORC09TransactionDate = JustDate_"0000"

	}
	else
	{
		set pResp.ORC09TransactionDate = SQLDate
	}

	set pResp.ORC12OrderingProvider = resultRecord.getString(7)

	if $L(pResp.ORC12OrderingProvider) '= 0
	{
		set hddRepReq = ##class(IHC.ITF.ITFCOMMON.HDD.Interface.Utility).CreateHddRepReqObject()
		do ##class(IHC.ITF.ITFCOMMON.HDD.Interface.Utility).AddNcidToRepObject(hddRepReq , resultRecord.getString(7), 1309, "ORC12")

		set tStatus=..SendRequestSync(..HddTargetConfigName,hddRepReq,.hddResponse)
 		if ('tStatus) 
 		{
    	 set status=##class(IHC.ITF.ITFCOMMON.Utility).ItfGeneralError(..%ConfigName,"Unexpected HDD response returned or HDD call failure") 
	    }
 		else 
 		{ 
   			set hddLookRes  = hddResponse 
 		}

 		set OrderingProvider=##class(IHC.ITF.ITFCOMMON.HDD.Interface.Utility).GetHddObject(hddLookRes , "ORC12")
 		set pResp.ORC12OrderingProvider = OrderingProvider.Rep
	}
	else
	{
		set pResp.ORC12OrderingProvider = ""
	}

	return $$$OK

	//Set RXO1.1
	//Check if entry exsists for Drug_Ncid in H2TRANSLATOR. if so copy the source_id from H2TRANSLATOR else check processed orders-
	//-if record exists in Processed orders copy the OriginalSynID else leave the field blank

	Do ..H2TranslatorStmt.setLong(1,resultRecord.getString(9))
	set tResultRXO01 = ..H2TranslatorStmt.executeQuery()

	// If entry exists in H2TRANSLATOR, copy the source_id from H2TRANSLATOR to ORM1.1 and NCID_txt to RXO1.2
	if tResultRXO01.next() 
	{
		set pResp.RXO0101RequestCode = tResultRXO01.getString(2)
		set pResp.RXO0102CodeDescription = tResultRXO01.getString(8) //Setting RXO1.2 here itself
		set pResp.RXO0103CodeMethod = tResultRXO01.getString(4)
	}
	elseif ..isPreProcessed = 0 //check processed orders exists for the record. If so copy the OriginalSynID
	{	
		Do ..ProcessedOrdersStmt.setLong(1,resultRecord.getString(2))
		set tResultSynID = ..ProcessedOrdersStmt.executeQuery()

	// If entry exists in PROCESSEDORDERS, copy the OriginalSynID from PROCESSEDORDERS to ORM1.1 
		if tResultSynID.next() 
		{
			set pResp.RXO0101RequestCode = tResultSynID.getString(5)

		}

	}
	else
	{
		set pResp.RXO0101RequestCode = ""
	}

	do tResultRXO01.close() //Closing the ResultSet

	//Set ORM1.2
	//Check if ORM1.2 is already set in above process for ORM1.1. if not we need to do the HDD call for NCID to REP
	if $L(pResp.RXO0102CodeDescription) = 0
	{
		set pResp.DrugNcid = resultRecord.getString(9) // Setting this value to do NCIDToRep in Bpl as we are not able to do NCIDToRep here
		if ($L(pResp.DrugNcid) '= 0)
		{
			set hddRepReq = ##class(IHC.ITF.ITFCOMMON.HDD.Interface.Utility).CreateHddRepReqObject()
			do ##class(IHC.ITF.ITFCOMMON.HDD.Interface.Utility).AddNcidToRepObject(hddRepReq , resultRecord.getString(9), 2000, "RXO0102")

			set tStatus=..SendRequestSync(..HddTargetConfigName,hddRepReq,.hddResponse)
 			if ('tStatus) 
 			{
    		 set status=##class(IHC.ITF.ITFCOMMON.Utility).ItfGeneralError(..%ConfigName,"Unexpected HDD response returned or HDD call failure") 
	    	}
 			else 
 			{ 
   				set hddLookRes  = hddResponse 
 			}

 			set MedicationName=##class(IHC.ITF.ITFCOMMON.HDD.Interface.Utility).GetHddObject(hddLookRes , "RXO0102")
 			set pResp.RXO0102CodeDescription = MedicationName.Rep
		}

	}

	//Set ORM1.3
	if $L(pResp.RXO0103CodeMethod) = 0
	{
		set pResp.RXO0103CodeMethod = "M"
	}

	set pResp.RXO02RequestAmountMinimum = resultRecord.getString(13)
	set pResp.RXO03RequestAmountMaximum = resultRecord.getString(14)

	//Set ORM1.4. if both min and max amount are NOT null and only Req units ae null then set 91717 for ORM1.4
	if ($L(resultRecord.getString(13)) '= 0) && ($L(resultRecord.getString(14)) '= 0) && ($L(resultRecord.getString(15)) = 0)
	{
		set pResp.RXO04RequestGiveUnits = "91717"	
	}
	else
	{
		set pResp.RXO04RequestGiveUnits = resultRecord.getString(15)
	}

	set pResp.RXO09AllowSubstitutions = resultRecord.getString(24)
	set pResp.RXO11ReqDispenseAmt = resultRecord.getString(21)
	set pResp.RXO12ReqDispenseUnits = resultRecord.getString(22)

	if ($L(resultRecord.getString(23)) '= 0) && (resultRecord.getString(23) '= -1)
	{

		set pResp.RXO13NoOfRefills = resultRecord.getString(23)

	}
	else
	{
		set pResp.RXO13NoOfRefills = ""
	}

	return $$$OK

set pResp.NTE01SetID = "1"
set pResp.NTE02SourceComment = "O"

set ReplacedComment =""

if $L(resultRecord.getString(26)) '= 0
{
	set ReplacedComment = resultRecord.getString(26)
	set ReplacedComment = $REPLACE(ReplacedComment,$C(13,10),"~") //Replace a two-character sequence of Chr(13) and Chr(10) with '~'
	set ReplacedComment = $REPLACE(ReplacedComment,$C(10),"~") //Replace remaining Chr(10) with '~'
	set ReplacedComment = $REPLACE(ReplacedComment,$C(92),"\E\") //Replace Chr(92) with '\E\'
	set ReplacedComment = $REPLACE(ReplacedComment,"|",":") //Replace all '|' with ':'
	set ReplacedComment = $REPLACE(ReplacedComment,"^"," ") //Replace all '^' with ' '
}

//set NTE03Comment

if ($L(resultRecord.getString(26)) = 0) && ($L(..SIGText)= 0) //Medication name only ( Staging.Comment and SIGText is empty) 
{
	set pResp.NTE03Comment = "Ordered as: "_pResp.RXO0102CodeDescription //Add Medication name in Bpl from RXO1.2 ( through HDD)
}

elseif ($L(resultRecord.getString(26)) '= 0) && ($L(..SIGText)= 0) //Medication name and Comment (Staging.Comment not empty and SIGText is empty)
{
	set pResp.NTE03Comment = "Ordered as: "_pResp.RXO0102CodeDescription_"~"_ReplacedComment //Adding Medication name(RXO1.2) after "Ordered as:" in Bpl from RXO1.2 ( through HDD)
}

elseif ($L(resultRecord.getString(26)) '= 0) && ($L(..SIGText)> 0)  //Medication name, SIG, and Comment (Staging.Comment not empty and SIGText not empty)
{
	set pResp.NTE03Comment = "Ordered as: "_pResp.RXO0102CodeDescription_"~"_..SIGText_"~"_ReplacedComment //Adding Medication name(RXO1.2) after "Ordered as:" in Bpl from RXO1.2 ( through HDD)
}

elseif ($L(resultRecord.getString(26)) = 0) && ($L(..SIGText)> 0)  //Medication name and SIG (Staging.Comment is empty and SIGText not empty)
{
	set pResp.NTE03Comment = "Ordered as: "_pResp.RXO0102CodeDescription_"~"_..SIGText //Adding Medication name(RXO1.2) after "Ordered as:" in Bpl from RXO1.2 ( through HDD)
}
else
{
	set pResp.NTE03Comment = "Ordered as: "_pResp.RXO0102CodeDescription_"~"_ReplacedComment
}

return $$$OK

	set isConvertToText =1
	set isConverstionRuleApplied = 0 // 0 is false
	set FreqText = ""
	set PrnFlag = "N"

	set FreqAbstOrderCount=..GetFrequencyTableRowCount(resultRecord.getString(2))

	// Getting records from FREQUENCY_ABSTRACT table 
	Do ..FreqAbstractStmt.setLong(1,resultRecord.getString(2))
	set FreqAbstResult = ..FreqAbstractStmt.executeQuery()


	do FreqAbstResult.next()
	//Text will be transferred to Cerner when:
    //  1. There is more than 1 row of frequencies for the order - OR –
    //  2. There is only 1 frequency, but it is not a named frequency - OR –
    //  3. There is only one frequency and it is named, but cannot be translated to a Cerner code.


	if FreqAbstOrderCount = 0    // if no records 
	{
		set isConvertToText = 0
		set pResp.ORC07QuantityTiming = "" //Scenario 1 - No Frequency_Abstract rows. The case is simple; Timing/Quantity is Null in the ORC segment.
		return $$$OK
	}

	// Check if only one 1 row exists in FREQUENCY_ABSTRACT table 
	if FreqAbstOrderCount > 1    
	{
		set isConvertToText = 0
	}
	elseif $L(FreqAbstResult.getString(4)) = 0 // Check if Named frequencey is empty 
	{
		set isConvertToText = 0
	} 
	else
	{
		// Check if Named Frequency NCID can be translated to Cerner Code
		//set FreqTranstQuery="select * from "_..DBSchema_".FREQUENCY_TRANSLATION where NCID=?" 
		Do ..FreqTranslationStmt.setLong(1,FreqAbstResult.getString(4))
		set FreqTranstResult = ..FreqTranslationStmt.executeQuery()


		if FreqTranstResult.next()
		{
			if FreqTranstResult.getString(5) = "N"
			{
				set isConvertToText = 0
			}
		}

	do FreqTranstResult.close() //Closing the ResultSet

	}

	set NamedFrequencyNCIDValue = FreqAbstResult.getString(4) // This variable is needed as we need to manipulate it in CoversionRules logic below and use in Scenario 2.1

	//Do Conversion Rules - Start
	if (isConvertToText = 0) && (FreqAbstOrderCount = 1) //if need to convert to text and only one Frequency_Abstract row
	{	
		if FreqAbstResult.getString(12) = "67655" // How_Often_Day_Week_ncid = 67655 (“every”), then copy value of Day_Of_Week_ncid into Named_Frequency_ncid value.
		{
			set NamedFrequencyNCIDValue = FreqAbstResult.getString(10)
			set isConverstionRuleApplied = 1
		}

		if ($L(FreqAbstResult.getString(5)) '= 0) && ($L(FreqAbstResult.getString(6)) '= 0)
		{
			// Get value from ORDERS2.FREQUENCY_CONVERSION
			Do ..FreqConversionStmt.setLong(1,FreqAbstResult.getString(5))
			Do ..FreqConversionStmt.setLong(2,FreqAbstResult.getString(6))
			set FreqConversionResult = ..FreqConversionStmt.executeQuery()

			// Set ConvertTo value from ORDERS2.FREQUENCY_CONVERSION into Named_Frequency_ncid
			if FreqConversionResult.next()
			{
				if '""=FreqConversionResult.getString(8)
				{
					set NamedFrequencyNCIDValue = FreqConversionResult.getString(8)
					set isConverstionRuleApplied = 1
				}
			}

			do FreqConversionResult.close() //Closing the ResultSet
		}

	}

	//Do Conversion Rules - END

	if (isConvertToText = 1) || (isConverstionRuleApplied = 1) //Scenario 2.1 - One Frequency_Abstract row and has a Named_Frequency_ncid value and can be translated in Cerner
	{
		// Check For PRN Flag with the current namedfrequencyNCID ( it might be changed if conversionrule is applied else it remains same)
		//set FreqTranstQuery="select * from "_..DBSchema_".FREQUENCY_TRANSLATION where NCID=?"
		Do ..FreqTranslationStmt.setLong(1,FreqAbstResult.getString(4))
		set FreqTranstResult = ..FreqTranslationStmt.executeQuery()

		if FreqTranstResult.next()
		{
			set PrnFlag = FreqTranstResult.getString(4)
		}

			//Check if PRN flag rules apply
			if PrnFlag = "Y" // Checking if PRN flag in FREQUENCY_TRANSLATION table is "Y"
			{
				set pResp.ORC07QuantityTiming = "^"_NamedFrequencyNCIDValue_"^^^^PRN" //Create Timing quatity as ‘^’ + Named_Frequency_ncid value + ‘^^^^PRN’
			}
			else // PRN flag is "N"
			{
				set pResp.ORC07QuantityTiming = "^"_NamedFrequencyNCIDValue  //Create Timing quatity as ‘^’ + Named_Frequency_ncid value
			}

			//If Named NCID value itself is PRN(1534)
			if FreqAbstResult.getString(4) = "1534"  //If the Named Frequency is equal to ‘PRN’ (ncid=1534), then change the Named_Frequency_ncid to value 156950 (‘As Directed’) and set the PRN Flag to true.
			{
				set pResp.ORC07QuantityTiming = "^156950^^^^PRN"
			}

			do FreqTranstResult.close() //Closing the ResultSet


	}
	else //Scenario 2.2 - One/Many Frequency_Abstract row and cannot be translated in Cerner
	{

		set pResp.ORC07QuantityTiming = ""   //The Timing / Quantity field in the ORC segment is left Null.

		if (FreqAbstOrderCount > 1) || (FreqAbstOrderCount = 1)
		{
			set counter = 1
			while ((counter < (FreqAbstOrderCount + 1)) && (FreqAbstOrderCount '= 0))
			{
				//if FreqAbstResult.getString(4)> 0 // If Named Frequency not null
				if $L(FreqAbstResult.getString(4)) '= 0
				{
					set FreqText = FreqText_..GetTransalationForNCID(FreqAbstResult.getString(4))_", " //Concat SIGText and add a space in the end.
				}
				if ($L(FreqAbstResult.getString(13)) '= 0) && ($L(FreqAbstResult.getString(14)) '= 0) // If How_often_Day_Month_ncid and Day_Of_Month_Value are both not Null
				{
					set FreqText = FreqText_..GetTransalationForNCID(FreqAbstResult.getString(14))_", "_FreqAbstResult.getString(13)_" day of the month"_", "
				}
				if ($L(FreqAbstResult.getString(4)) = 0) && ($L(FreqAbstResult.getString(10)) '= 0) && ($L(FreqAbstResult.getString(12))'= 0) //If Named_Frequency_ncid is null and (Day_of_Week_ncid and How_Often_Day_Week_ncid are not Null)
				{
					set FreqText = FreqText_..GetTransalationForNCID(FreqAbstResult.getString(12))_" "_..GetTransalationForNCID(FreqAbstResult.getString(10))_", "
				}
				if ($L(FreqAbstResult.getString(4)) = 0) && ($L(FreqAbstResult.getString(5))'= 0) //If Timed_Frequency_ncid is Not Null and Named_Frequency_ncid is Null
				{
					set FreqText = FreqText_"Every "_FreqAbstResult.getString(6)_" "_..GetTransalationForNCID(FreqAbstResult.getString(5))_", "
				}
				if $L(FreqAbstResult.getString(7)) '= 0 //If Range_Frequency_ncid is Not Null
				{
					set FreqText = FreqText_"Every "_FreqAbstResult.getString(8)_" to "_FreqAbstResult.getString(9)_" "_..GetTransalationForNCID(FreqAbstResult.getString(7))_", "
				}
				if $L(FreqAbstResult.getString(15)) '= 0 //If Text Frequency is Not Null
				{
					set FreqText = FreqText_" "_FreqAbstResult.getString(15)_", "
				}

                // Increment counter
                set counter = counter + 1

                //Move cursor to next row
               	do FreqAbstResult.next()
			}

			//After while loop If Freqtext is generated then add "/ Freq: to the Freqtext
			if $L(FreqText) '= 0
			{
				Set FreqText = $EXTRACT(FreqText,0,$L(FreqText)-2) // Removing the extra ","
				set FreqText = "/ Freq: "_FreqText
			}

		}

	}

	do FreqAbstResult.close()

			//Check the Transalation for Dose units

			set DoseText = ""
			if $L(resultRecord.getString(15)) '= 0 //Dose Units not null 
			{
					//set DoseQuery="select * from "_..DBSchema_".UNITS_MAP where DOSE_UNITS_NCID =?" 
					Do ..DoseStmt.setLong(1,resultRecord.getString(15))
					set DoseResult = ..DoseStmt.executeQuery()

					if DoseResult.next()
					{
						if DoseResult.getString(5) = "N"
						{
							set DoseText = "Dose units: "_DoseResult.getString(2)
						}
					}

					do DoseResult.close() //Closing the ResultSet
			}


			//Check the Transalation for Route 

			set RouteText = ""
			if $L(resultRecord.getString(16)) '= 0 //Route not null 
			{
					//set RouteQuery="select * from "_..DBSchema_".ROUTE_MAP where ROUTE_METHOD_NCID = ?" 
					Do ..RouteStmt.setLong(1,resultRecord.getString(16))
					set RouteResult =  ..RouteStmt.executeQuery()

					if RouteResult.next()
					{
						if RouteResult.getString(5) = "N"
						{
							set RouteText = "/ Route: "_RouteResult.getString(2)
						}
					}

					do RouteResult.close() //Closing the ResultSet
			}


			//Check the Transalation for Dispensing units 

			set DispensingText = ""
			if $L(resultRecord.getString(22)) '= 0 //Dispensing Units not null 
			{
					//set DispensingQuery="select * from "_..DBSchema_".UNITS_MAP where DOSE_UNITS_NCID =?" 
					Do ..DispensingStmt.setLong(1,resultRecord.getString(22))
					set DispensingResult = ..DispensingStmt.executeQuery()

					if DispensingResult.next()
					{
						if DispensingResult.getString(5) = "N"
						{
							set DispensingText = "/ Dispense Units: "_DispensingResult.getString(2)
						}
					}

					do DispensingResult.close() //Closing the ResultSet
			}


			//Construct SIGText

			if ($L(DoseText) = 0) && ($L(RouteText) = 0) && ($L(DispensingText) = 0) && ($L(FreqText) = 0) // If no transaltion took place then SIGText is empty
			{
				set ..SIGText =""
			}
			else
			{
				set ..SIGText ="SIG: "_DoseText_RouteText_DispensingText_FreqText //Creating the Final SIGText	
			}

Do ..TranslationStmt.setLong(1,ncid)
set pResult = ..TranslationStmt.executeQuery()

	if pResult.next()
	{
      	set TranslatedText = pResult.getString(2) 
      	do pResult.close()
      	return TranslatedText // Return the Transalted Text
	}

	do pResult.close()
	return ""

Do ..FreqCountStmt.setLong(1,EventID)
set pRowResult =  ..FreqCountStmt.executeQuery()

	if pRowResult.next()
	{
      	set RowCount = pRowResult.getString(1) 	      	
      	do pRowResult.close() //Closing ResultSet
      	return RowCount // Return the rowcount
	}

	do pRowResult.close() //Closing ResultSet
	return 0


// Filtering logic Starts

	//Check if Order Date less than 01/01/2012 then filter it and Set processed as Y
	Set extractSQLDate = $EXTRACT(resultRecord.getString(4),0,10)
	set DiffADate =  $System.SQL.DATEDIFF("d","01/01/2012",extractSQLDate)
	if DiffADate <= 0
	{
	    //Setting Processed Flag as "Y" in Staging
		//TODO Remove set upStatus = ..UpdatePreviousProcessed("Y",resultRecord.getString(2))
		return 1	// Record filtered
	}

	//Check if it is a Text Order
	if $L(resultRecord.getString(9)) = 0
	{
		//Setting Processed Flag as "Y" in Staging
		//TODO Remove set upStatus = ..UpdatePreviousProcessed("Y",resultRecord.getString(2))
		return 1
	}

	// Check if Order Status is either Discontinued or Error and If not PrevProcessed 
	if (resultRecord.getString(6) = 1524) || (resultRecord.getString(6) = 69074) && (..isPreProcessed = 1)
	{
		//Setting Processed Flag as "Y" in Staging
	    set isdiscontinuedOrError = 0 // Setting flag which is used in updating ProcessedOrder Table
		//TODO Remove set upStatus = ..UpdatePreviousProcessed("Y",resultRecord.getString(2))			
		return 1	
	}

	return 0

//Check if it is PreProcessed  orders then update the ProcessedOrders Table
if ..isPreProcessed = 0 
{
	set ..editVersion = ..editVersion + 1
	Do ..UpdateProcessedOrderStmt.setLong(1,..editVersion)
	Do ..UpdateProcessedOrderStmt.setLong(2,eventID)
	Do ..UpdateProcessedOrderStmt.executeUpdate()	
}
else
{		 	
	Do ..InsertProcessedOrderStmt.setLong(1,eventID)
	Do ..InsertProcessedOrderStmt.setLong(2,pResp.PID02AltPatientID)
	Do ..InsertProcessedOrderStmt.setLong(3,pResp.RXO0101RequestCode)
	Do ..InsertProcessedOrderStmt.executeUpdate()	 	 	
}

return $$$OK

set Hl7 = "MSH|^~\&|"_pResp.MSH03SendingApp_"|"_pResp.MSH04SendingFac_"|"_pResp.MSH05ReceiveApp_"||||"_pResp.MSH0901Type_"^"_pResp.MSH0902Event_"||"_pResp.MSH11ProcessMode_"|"_pResp.MSH12VersionId_"|"_$C(13,10)
_"EVN|O01|"_$C(13,10)
_"PID|"_pResp.PID01_"|"_pResp.PID02AltPatientID_"|||"_pResp.PID05PatientName_"|"_$C(13,10)
_"ORC|"_pResp.ORC01OrderControl_"|"_pResp.ORC0201UniquePlacerNo_"^"_pResp.ORC0202PlacerAppId_"|||"_pResp.ORC05OrderStatus_"||"_pResp.ORC07QuantityTiming_"||"_pResp.ORC09TransactionDate_"|||"_pResp.ORC12OrderingProvider_"|"_$C(13,10)
_"RXO|"_pResp.RXO0101RequestCode_"^"_pResp.RXO0102CodeDescription_"^"_pResp.RXO0103CodeMethod_"^|"_pResp.RXO02RequestAmountMinimum_"|"_pResp.RXO03RequestAmountMaximum_"|"_pResp.RXO04RequestGiveUnits_"|||||"_pResp.RXO09AllowSubstitutions_"||"_pResp.RXO11ReqDispenseAmt_"|"_pResp.RXO12ReqDispenseUnits_"|"_pResp.RXO13NoOfRefills_"|"_$C(13,10)
_"NTE|"_pResp.NTE01SetID_"|"_pResp.NTE02SourceComment_"|"_pResp.NTE03Comment_"|"

if ($L(pResp.RXR01Route) '= 0)
{
	set Hl7 = Hl7_$C(13,10)_"RXR|"_pResp.RXR01Route_"|"
}

//set Hl7 = Hl7_$C(13,10)_"OBR|{"_pResp.EventID

return Hl7
